\begin{theorem}
Suppose that Assumptions~\ref{a:H} and \ref{a:g} hold. Let $(\bar{x}^k,\bar{y}^k)$ be the sequence generated by Algorithm~\ref{algo} with $\mu_k =\mu_1 k^{-\min\{\theta, \frac{1-\theta}{2}\}}$. Then, for $\hat{x}^k=\bar{x}^k$ and $\hat{y}^k=\bar{y}^k-A^*(AA^*)^{-1}(A\bar{y}^k-\prox_{\mu g}(A\bar{y}^k))$, it holds that
\begin{multline*}
\min_{1\leq j\leq k}(\dist(-\nabla_yH(\hat{x}^j,\hat{y}^j),A^*\partial g(A\hat{y}^j))+\dist(0,G_{\sigma_j}(\hat{x}^j,\hat{y}^j))) \\ \leq (\Theta +(L_{12}+L_{12})L_g\sigma_{\min}(A)^{-1}\mu_1)k^{-\min\{\theta, \frac{1-\theta}{2}\}},
\end{multline*}
where $\Theta :=\sqrt{2(\ln 2)^{-1}M^{-1}(\mathcal{L}_{\mu_1}(\bar{x}^1,\bar{y}^1)-\mathcal{L}^*+\mu_1L_g^2)}$ and
\begin{align*}
M :=\min\left\{\frac{(1 -\alpha^2)\eta}{2} -\frac{L_{12}^2(1+\alpha)^2\eta}{2L_{11}(L_{22} +2\rho\|A\|^2)}, \frac{(2 -L_{11}\beta\sigma)\beta\gamma}{4}, \frac{(2 -L_{11}\sigma)\gamma}{4}\right\}.
\end{align*}
\end{theorem}

