\begin{lemma}[{\cite[Theorem 2.64]{BC}}]
\label{l:descent}
Let $F:\mathbb{R}^n\rightarrow \mathbb{R}$ be a continuously differentiable function whose gradient $\nabla F$ is $L$-Lipschitz continuous with $L>0$. Then, for all $x,y\in \mathbb{R}^n$,
\begin{align*}
|F(y)-F(x)-\langle\nabla F(x),y-x\rangle|\leq\frac{L}{2}\|y-x\|^2.
\end{align*}
\end{lemma}

\begin{lemma}
\label{l:weakcvx}
Let $F: \mathbb{R}^n\rightarrow (-\infty,+\infty]$ be a proper $\rho$-weakly convex and lower semicontinuous function, and let $\mu \in(0,1/\rho)$. Then
\begin{enumerate}
\item
\cite[Corollary 3.4]{HLO} The Moreau envelope function $F_{\mu}$ is continuously differentiable on $\mathbb{R}^n$ and, for all $x\in \mathbb{R}^n$,
\begin{align*}
\nabla F_{\mu}(x) =\frac{1}{\mu}(x-\prox_{\mu F}(x)).
\end{align*}
This gradient is $\max\{\frac{1}{\mu},\frac{\rho}{1-\rho \mu}\}$-Lipschitz continuous.
\item\label{l:weakcvx_inclu}
\cite[Lemma 3.2]{BW} $\nabla{F_{\mu}(x)}\in \partial F(\prox_{\mu F}(x))$.
\end{enumerate}
\end{lemma}

\begin{lemma}[{\cite[Lemma 3.3]{BW}}]\label{2.6} Let $F: \mathbb{R}^n\rightarrow (-\infty,\infty)$ be a $\rho$-weakly convex function and $L_F$-Lipschitz continuous, and let $\mu \in (0,1/\rho)$. Then the Moreau envelope $F_\mu$ is Lipschitz continuous and, for all $x\in \mathbb{R}^n$,
\begin{align*}
\|\nabla F_\mu(x)\|\leq L_F \text{~~and~~} \|x-\prox_{\mu F}(x)\|\leq \mu L_F.
\end{align*}
\end{lemma}

\begin{lemma}[{\cite[Lemma~\ref{l:LL}]{BW}}]
\label{l:MoreauEnv}
Let $F: \mathbb{R}^n\rightarrow (-\infty,+\infty]$ be a proper $\rho$-weakly convex lower semicontinuous function, let $\mu_1$ and $\mu_2$ be parameters such that $0< \mu_2 \leq \mu_1 < 1/\rho$. Then
\begin{align*}
F_{\mu_2}(x)\leq F_{\mu_1}(x)+\frac{\mu_1(\mu_1-\mu_2)}{2\mu_2}\|
\nabla F_{\mu_1}(x)\|^2.
\end{align*}
If $F$ is additionally $L_F$-Lipschitz continuous, then
\begin{align*}
F_{\mu_2}\leq F_{\mu_1}+\frac{\mu_1(\mu_1-\mu_2)}{2\mu_2}(L_F)^2.
\end{align*}
\end{lemma}

\begin{lemma}\label{l:estimate}
Let $x\in [1, +\infty)$ and $\alpha\in [0, 1]$. Then
\begin{align*}
(1 +x)^{\alpha} - 1 \geq \alpha (\ln 2) x^{\alpha}.
\end{align*}
\end{lemma}

\begin{proof}
Let $\varphi(x) :=(1 +x)^{\alpha} -1 - \alpha (\ln 2) x^{\alpha}$. Then $\psi(\alpha) =:\varphi(1) =2^{\alpha} -1 -\alpha \ln 2$. We see that, for all $\alpha \geq 0$,
$\psi'(\alpha) =(\ln 2) (2^{\alpha} -1) \geq 0$. It follows that $\varphi(1) =\psi(\alpha) \geq \psi(0) =0$.

On the other hand,
\begin{align*}
\varphi'(x) =\alpha(1 +x)^{\alpha -1} -\alpha^2 (\ln 2) x^{\alpha -1} =\alpha x^{\alpha -1}\left(\left(1 +\frac{1}{x}\right)^{\alpha -1} -\alpha \ln 2\right).
\end{align*}
As $x \geq 1$ and $\alpha -1 \leq 0$, it holds that
\begin{align*}
\left(1 +\frac{1}{x}\right)^{\alpha -1} -\alpha \ln 2 &\geq (1 + 1)^{\alpha -1} -\alpha \ln 2 =2^{\alpha} -2^{\alpha -1} -\alpha \ln 2 \\
&\geq 2^{\alpha} -1 -\alpha \ln 2 =\varphi(1) \geq 0.
\end{align*}
Therefore, for all $x\geq 1$, $\varphi'(x) \geq 0$, which implies that $\varphi(x) \geq \varphi(1) =0$. The proof is complete.
\end{proof}

\begin{remark}
\label{r:G(x,.)}
From the Lipschitz continuity of $\nabla_x H(x,\cdot)$ in Assumption~\ref{a:H}, we have that for all $x\in \mathbb{R}^n$ and all $y_1,y_2\in \mathbb{R}^m$,
\begin{align*}
\|G_\lambda(x,y_1)&-G_\lambda(x,y_2)\| \notag\\
&=\frac{1}{\lambda}\|\prox_{\lambda f}(x-\lambda \nabla_x H(x,y_2))-\prox_{\lambda f}(x-\lambda \nabla_x H(x,y_1))\| \\
&\leq\|\nabla_x H(x,y_1)-\nabla_x H(x,y_2)\| \\
&\leq L_{12}\|y_1-y_2\|.
\end{align*}
\end{remark}

\begin{lemma}
\label{l:transfer}
Suppose that Assumptions \ref{a:H} and \ref{a:g} hold, $A$ is surjective, and $\mu\in(0,1/\rho)$.
Let $\bar{x} =x^*\in \mathbb{R}^n$ and $\bar{y}=y^*-A^*(AA^*)^{-1}(Ay^*-\prox_{\mu g}(Ay^*))$ with $y^*\in \mathbb{R}^m$. Then
\begin{align*}
&\dist(0,G_\lambda(\bar{x},\bar{y}))+\dist(-\nabla_y H(\bar{x},\bar{y}),A^*\partial g(A\bar{y})) \\
&\leq \dist(0,G_\lambda(x^*,y^*)) +\dist(-\nabla_yH(x^*,y^*),A^*\partial g(\prox_{\mu g}(Ay^*)))\\
&\quad +(L_{12}+L_{22})L_g\sigma_{\min}(A)^{-1}\mu.
\end{align*}
Consequently, if $(x^*,y^*)$ is an $\varepsilon$-approximate stationary point of problem~\eqref{guanghua}, then $(\bar{x},\bar{y})$ is an $\bar{\varepsilon}$-approximate stationary point of problem~\eqref{eq:L1E1} with $\bar{\varepsilon} =\varepsilon +(L_{12}+L_{22})L_g\sigma_{\min}(A)^{-1}\mu$.
\end{lemma}

\begin{proof}
Since $\bar{y}=y^*-A^*(AA^*)^{-1}(Ay^*-\prox_{\mu g}(Ay^*))$, multiplying both sides by $A$ yields $A\bar{y}=\prox_{\mu g}(Ay^*)$. We have that
\begin{align*}
&\dist(-\nabla_yH(\bar{x},\bar{y}),A^*\partial g(A\bar{y})) \\
&\leq \dist(-\nabla_yH(x^*,y^*),A^*\partial g(A\bar{y})) +\|\nabla_yH(x^*,y^*)-\nabla_yH(\bar{x},\bar{y})\| \\
&=\dist(-\nabla_yH(x^*,y^*),A^*\partial g(\prox_{\mu g}(Ay^*))) +\|\nabla_yH(x^*,y^*)-\nabla_yH(x^*,\bar{y})\| \\
&\leq \dist(-\nabla_yH(x^*,y^*),A^*\nabla g_{\mu}(Ay^*)) +L_{22}\|y^* -\bar{y}\|,
\end{align*}
where the last inequality uses $A^*\nabla g_{\mu}(Ay^*)\in A^*\partial g(\prox_{\mu g}(Ay^*))$ (see Lemma~\ref{l:weakcvx}\ref{l:weakcvx_inclu}) and the Lipschitz continuity of $\nabla_y H(x^*,\cdot)$.

Next, by Remark~\ref{r:G(x,.)},
\begin{align*}
\dist(0,G_\lambda(\bar{x},\bar{y})) &= \|G_\lambda(x^*,y^*) -G_\lambda(x^*,y^*) +G_\lambda(\bar{x},\bar{y})\| \\
&\leq \|G_\lambda(x^*,y^*)\| +\|G_\lambda(x^*,y^*) -G_\lambda(\bar{x},\bar{y})\| \\
&= \dist(0,G_\lambda (x^*,y^*)) +\|G_\lambda(x^*,y^*) -G_\lambda(x^*,\bar{y})\| \\
&\leq \dist(0,G_\lambda (x^*,y^*)) +L_{12}\|y^* -\bar{y}\|.
\end{align*}
Note that
\begin{align*}
\|y^* -\bar{y}\| =\|A^*(AA^*)^{-1}(Ay^*-\prox_{\mu g}(Ay^*))\| \leq \sigma_{\min}(A)^{-1}\mu L_g
\end{align*}
due to Lemma~\ref{2.6} and the fact that the operator norm of $A^*(AA^*)^{-1}$ is bounded by the inverse of the smallest singular value $\sigma_{\min}(A)$ of $A$, i.e., $\|A^*(AA^*)^{-1}\|\leq\sigma_{\min}(A)^{-1}$. Altogether, we obtain that
\begin{align*}
&\dist(0,G_\lambda(\bar{x},\bar{y})) +\dist(-\nabla_y H(\bar{x},\bar{y}),A^*\partial g(A\bar{y})) \\
&\leq   \dist(0,G_\lambda(x^*,y^*)) +\dist(-\nabla_yH(x^*,y^*),A^*\partial g(\prox_{\mu g}(Ay^*))) \\
&\quad+(L_{12} +L_{22})L_g\sigma_{\min}(A)^{-1}\mu,
\end{align*}
which completes the proof.
\end{proof}

Recalling that $G_\lambda(x,y) =\frac{1}{\lambda}(x -\prox_{\lambda f}(x -\lambda\nabla_x  H(x,y)))$, we have
\begin{align}\label{zhu4.2}
x^{k+1}&=\prox_{\sigma_k f}(\bar{x}^k-\sigma_k\nabla_x H(\bar{x}^k,\bar{y}^{k+1}))\notag \\
&=\bar{x}^k-\sigma_k\left(\frac{1}{\sigma_k}(\bar{x}^k-\prox_{\sigma_k f}(\bar{x}^k-\sigma_k\nabla_x H(\bar{x}^k,\bar{y}^{k+1})))\right)\notag \\
&=\bar{x}^k-\sigma_k G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1}).
\end{align}

\begin{lemma}
\label{l:LL}
Suppose that Assumptions \ref{a:H} and \ref{a:g} hold. Let $(\bar{x}^k,\bar{y}^k)$ be the sequence generated by Algorithm~\ref{algo}. Then
\begin{align*}
\mathcal{L}_{\mu_{k}}(\bar{x}^{k+1},\bar{y}^{k+1}) &\leq \mathcal{L}_{\mu_{k}}(\bar{x}^k,\bar{y}^k)
-\frac{1}{2}\delta\tau_k\|A^*\nabla g_{\mu_k}(A\bar{y}^k)+\nabla_y H(\bar{x}^k,\bar{y}^k)\|^2\notag \\
&\quad -\frac{1}{4}\kappa\sigma_k\|G_{\sigma_k}(\bar{x}^k,\bar{y}^k)\|^2 +(\mu_k-\mu_{k+1})L_g^2,
\end{align*}
where $\delta :=1 -\alpha^2 -\frac{L_{12}^2(1+\alpha)^2}{L_{11}(L_{22} +2\rho\|A\|^2)} >0$ and $\kappa :=\min\{(2 -L_{11}\beta\sigma)\beta, 2 -L_{11}\sigma\} >0$.
\end{lemma}

\begin{proof}
From the Lipschitz continuity of $\nabla_x \Phi_k(\cdot,\bar{y}^{k+1})$ and $\nabla_y\Phi_k(\bar{x}^k, \cdot)$, Lemma \ref{l:descent} implies that
\begin{align*}
\Phi_k(\bar{x}^{k+1},\bar{y}^{k+1}) &\leq\Phi_k(\bar{x}^{k},\bar{y}^{k+1}) +\langle\nabla_x\Phi_k(\bar{x}^k,\bar{y}^{k+1}),\bar{x}^{k+1}-\bar{x}^k\rangle+\frac{L_{11}}{2}\|\bar{x}^{k+1}-\bar{x}^k\|^2, \\
\Phi_k(\bar{x}^k,\bar{y}^{k+1}) &\leq \Phi_k(\bar{x}^k,\bar{y}^k) +\langle\nabla_y\Phi_k(\bar{x}^k,\bar{y}^k),\bar{y}^{k+1}-\bar{y}^k\rangle+\frac{L_k}{2}\|\bar{y}^{k+1}-\bar{y}^k\|^2.
\end{align*}
We note that
\begin{align}\label{eq:grad_y Phi_k}
\nabla_y\Phi_k(\bar{x}^k,\bar{y}^k) =A^*\nabla g_{\mu_k}(A\bar{y}^k)+\nabla_y H(\bar{x}^k,\bar{y}^k)
\end{align}
and from \eqref{s21}, \eqref{s41}, \eqref{s42}, and \eqref{zhu4.2} that
\begin{align*}
\bar{x}^{k+1}-\bar{x}^k &=\beta_k(x^{k+1}-\bar{x}^k)=-\beta_k\sigma_k G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1}), \\
\bar{y}^{k+1}-\bar{y}^k &=(1+\alpha_k)(y^{k+1}-\bar{y}^k) =-(1+\alpha_k)\tau_k \nabla_y\Phi_k(\bar{x}^k,\bar{y}^k).
\end{align*}
Therefore,
\begin{align}\label{8.7}
&\Phi_k(\bar{x}^{k+1},\bar{y}^{k+1}) \notag \\
&\leq \Phi_k(\bar{x}^k,\bar{y}^k) +\langle\nabla_x\Phi_k(\bar{x}^k,\bar{y}^{k+1}),\bar{x}^{k+1}-\bar{x}^k\rangle+\frac{L_{11}}{2}\|\bar{x}^{k+1}-\bar{x}^k\|^2 \notag \\
&\quad +\langle\nabla_y\Phi_k(\bar{x}^k,\bar{y}^k),\bar{y}^{k+1}-\bar{y}^k\rangle+\frac{L_k}{2}\|\bar{y}^{k+1}-\bar{y}^k\|^2 \notag \\
&= \Phi_k(\bar{x}^k,\bar{y}^k) -\beta_k\sigma_k\langle\nabla_x\Phi_k(\bar{x}^k,\bar{y}^{k+1}),G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\rangle \notag \\
&\quad +\frac{1}{2}L_{11}\beta_k^2\sigma_k^2\|G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\|^2 \notag\\
&\quad -\frac{1}{2}(2 +2\alpha_k -L_k(1+\alpha_k)^2\tau_k)\tau_k\|\nabla_y\Phi_k(\bar{x}^k,\bar{y}^k)\|^2.
\end{align}
By Lemma \ref{l:MoreauEnv} and the fact that $\mu_{k+1}\in [\mu_k/2, \mu_k]$,
\begin{align}\label{8.8}
g_{\mu_{k+1}}(Ay)\leq g_{\mu_k}(Ay) +\frac{\mu_k(\mu_k-\mu_{k+1})}{2\mu_{k+1}}L_g^2\leq g_{\mu_k}(Ay) +(\mu_k-\mu_{k+1})L_g^2.
\end{align}
Adding $H(x,y)$ to both sides of \eqref{8.8} yields
\begin{align}\label{3.4}
\Phi_{k+1}(x,y)\leq \Phi_k(x,y) +(\mu_k-\mu_{k+1})L_g^2.
\end{align}
Letting $x =\bar{x}^{k+1}$, $y =\bar{y}^{k+1}$ in \eqref{3.4} and combining it with \eqref{8.7}, we obtain that
\begin{align}\label{4.4}
&\Phi_{k+1}(\bar{x}^{k+1},\bar{y}^{k+1}) \notag \\
&\leq \Phi_k(\bar{x}^k,\bar{y}^k) -\beta_k\sigma_k\langle\nabla_x\Phi_k(\bar{x}^k,\bar{y}^{k+1}),G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\rangle \notag \\
&\quad +\frac{1}{2}L_{11}\beta_k^2\sigma_k^2\|G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\|^2 \notag\\
&\quad -\frac{1}{2}(2 +2\alpha_k -L_k(1+\alpha_k)^2\tau_k)\tau_k\|\nabla_y\Phi_k(\bar{x}^k,\bar{y}^k)\|^2 +(\mu_k-\mu_{k+1})L_g^2.
\end{align}
By the first-order optimality condition of \eqref{s31},
\begin{align*}
0\in \partial f(x^{k+1})+\frac{1}{\sigma_k}(x^{k+1}-\bar{x}^k+\sigma_k\nabla_x H(\bar{x}^k,\bar{y}^{k+1})),
\end{align*}
or equivalently,
\begin{align*}
\frac{1}{\sigma_k}(\bar{x}^k -x^{k+1}) -\nabla_x H(\bar{x}^k,\bar{y}^{k+1})\in \partial f(x^{k+1}).
\end{align*}
Combining with the convexity of $f$ and \eqref{zhu4.2}, it follows that
\begin{align}\label{8.9}
f(x^{k+1}) &\leq f(\bar{x}^k) -\left\langle \frac{1}{\sigma_k}(\bar{x}^k -x^{k+1}) -\nabla_x H(\bar{x}^k,\bar{y}^{k+1}), \bar{x}^k -x^{k+1}\right\rangle \notag \\
&= f(\bar{x}^k) -\frac{1}{\sigma_k}\|\bar{x}^k -x^{k+1}\|^2 +\langle \nabla_x H(\bar{x}^k,\bar{y}^{k+1}), \bar{x}^k -x^{k+1}\rangle\notag \\
&= f(\bar{x}^k) -\sigma_k\|G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\|^2 +\sigma_k\langle\nabla_x H(\bar{x}^k,\bar{y}^{k+1}),G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\rangle.
\end{align}
Again by the convexity of $f$ and \eqref{s42},
\begin{align*}
f(\bar{x}^{k+1})&=f\big(\beta_k x^{k+1}+(1-\beta_k)\bar{x}^k\big)
\leq \beta_k f(x^{k+1})+(1-\beta_k)f(\bar{x}^k).
\end{align*}
This together with \eqref{8.9} gives
\begin{align}\label{4.5}
f(\bar{x}^{k+1})&\leq f(\bar{x}^k) -\beta_k\sigma_k\|G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\|^2 \notag \\
&\quad +\beta_k\sigma_k\langle\nabla_xH(\bar{x}^k,\bar{y}^{k+1}),G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\rangle.
\end{align}
We now combine \eqref{4.4} and \eqref{4.5} to obtain
\begin{align}\label{4.10}
&\mathcal{L}_{\mu_{k}}(\bar{x}^{k+1},\bar{y}^{k+1}) \notag \\
&\leq \mathcal{L}_{\mu_{k}}(\bar{x}^k,\bar{y}^k) -\frac{1}{2}(2 +2\alpha_k -L_k(1+\alpha_k)^2\tau_k)\tau_k\|\nabla_y\Phi_k(\bar{x}^k,\bar{y}^k)\|^2 \notag \\ &\quad -\frac{1}{2}(2 -L_{11}\beta_k\sigma_k)\beta_k\sigma_k\|G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\|^2 +(\mu_k-\mu_{k+1})L_g^2.
\end{align}
Next, using Remark~\ref{r:G(x,.)},
\begin{align*}
\|G_{\sigma_k}(\bar{x}^k,\bar{y}^k)\|&=\|G_{\sigma_k}(\bar{x}^k,\bar{y}^k)-G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})+G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\|\notag \\
&\leq\|G_{\sigma_k}(\bar{x}^k,\bar{y}^k)-G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\|+\|G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\|\notag \\
&\leq L_{12}\|\bar{y}^{k+1}-\bar{y}^k\|+\|G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\|.
\end{align*}
Squaring and applying the inequality $\frac{1}{2}(a+b)^2 \leq a^2 +b^2$, we get
\begin{align*}
\frac{1}{2}\|G_{\sigma_k}(\bar{x}^k,\bar{y}^k)\|^2 &\leq L_{12}^2\|\bar{y}^{k+1}-\bar{y}^k\|^2 +\|G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\|^2 \\
&= L_{12}^2(1+\alpha_k)^2\tau_k^2\|\nabla_y\Phi_k(\bar{x}^k,\bar{y}^k)\|^2 +\|G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\|^2.
\end{align*}
which, combined with \eqref{eq:grad_y Phi_k} and \eqref{4.10}, implies that
\begin{align*}
\mathcal{L}_{\mu_{k}}(\bar{x}^{k+1},\bar{y}^{k+1}) &\leq \mathcal{L}_{\mu_{k}}(\bar{x}^k,\bar{y}^k) -\frac{1}{2}\delta_k\tau_k\|A^*\nabla g_{\mu_k}(A\bar{y}^k)+\nabla_y H(\bar{x}^k,\bar{y}^k)\|^2 \notag \\
&\quad -\frac{1}{4}\kappa_k\sigma_k\|G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\|^2 +(\mu_k-\mu_{k+1})L_g^2,
\end{align*}
where
\begin{align*}
\delta_k &:=2 +2\alpha_k -L_k(1+\alpha_k)^2\tau_k -(2 -L_{11}\beta_k\sigma_k)\sigma_k\beta_kL_{12}^2(1+\alpha_k)^2\tau_k, \\
\kappa_k &:=(2 -L_{11}\beta_k\sigma_k)\beta_k.
\end{align*}
Noting that $\tau_k\leq 1/L_k$ and that
\begin{align*}
(2 -L_{11}\beta_k\sigma_k)\sigma_k\beta_k\leq \frac{1}{L_{11}}\left(\frac{2 -L_{11}\beta_k\sigma_k +L_{11}\beta_k\sigma_k}{2}\right)^2 =\frac{1}{L_{11}},
\end{align*}
we have
\begin{align*}
\delta_k &\geq 2 +2\alpha_k -(1+\alpha_k)^2 -\frac{L_{12}^2}{L_{11}L_k}(1+\alpha_k)^2 \\
&= 1 -\alpha_k^2 -\frac{L_{12}^2}{L_{11}L_k}(1+\alpha_k)^2 \\
&\geq \delta =1 -\alpha^2 -\frac{L_{12}^2(1+\alpha)^2}{L_{11}(L_{22} +2\rho\|A\|^2)},
\end{align*}
where the last inequality follows from from the fact that $\alpha_k\in [-\alpha, \alpha]\subseteq [-1, \alpha]$ and that $L_k =L_{22} +\|A\|^2\max\{\frac{1}{\mu_k}, \frac{\rho}{1 -\rho\mu_k}\}\geq L_{22} +2\rho\|A\|^2$ since
\begin{align*}
\max\left\{\frac{1}{\mu_k}, \frac{\rho}{1 -\rho\mu_k}\right\} =\begin{cases}
\frac{1}{\mu_k} &\text{if~} 0 < \mu_k \leq \frac{1}{2\rho}, \\
\frac{\rho}{1 -\rho\mu_k} &\text{if~} \frac{1}{2\rho} < \mu_k < \frac{1}{\rho}.
\end{cases}
\end{align*}
Finally, we derive from $\sigma_k\in \sigma$ and $\beta_k\in [\beta, 1]$ that
\begin{align*}
\kappa_k =(2 -L_{11}\beta_k\sigma_k)\beta_k \geq (2 -L_{11}\beta_k\sigma)\beta_k \geq \kappa =\min\{(2 -L_{11}\beta\sigma)\beta, 2 -L_{11}\sigma\}
\end{align*}
as $(2 -L_{11}\beta_k\sigma)\beta_k$ is a quadratic function of $\beta_k$ with leading coefficient $-L_{11}\sigma <0$. This completes the proof.
\end{proof}

\begin{lemma}
\label{l:e-stationary}
Suppose that Assumptions~\ref{a:H} and \ref{a:g} hold. Let $(\bar{x}^k,\bar{y}^k)$ be the sequence generated by Algorithm~\ref{algo}. Then
\begin{align*}
\min_{1\leq j\leq k}\left(\|A^*\nabla g_{\mu_j}(A\bar{y}^j)+\nabla_y H(\bar{x}^j,\bar{y}^j)\|+\|G_{\sigma_j}(\bar{x}^j,\bar{y}^j)\|\right)
\leq \Theta k^{\frac{\theta-1}{2}},
\end{align*}
where $\Theta :=\sqrt{2(\ln 2)^{-1}M^{-1}(\mathcal{L}_{\mu_1}(\bar{x}^1,\bar{y}^1)-\mathcal{L}^*+\mu_1L_g^2)}$ and
\begin{align*}
M :=\min\left\{\frac{(1 -\alpha^2)\eta}{2} -\frac{L_{12}^2(1+\alpha)^2\eta}{2L_{11}(L_{22} +2\rho\|A\|^2)}, \frac{(2 -L_{11}\beta\sigma)\beta\gamma}{4}, \frac{(2 -L_{11}\sigma)\gamma}{4}\right\}.
\end{align*}
\end{lemma}

\begin{proof}
According to Lemma~\ref{l:LL},
\begin{align}\label{4.10'}
\mathcal{L}_{\mu_{k}}(\bar{x}^{k+1},\bar{y}^{k+1}) &\leq \mathcal{L}_{\mu_{k}}(\bar{x}^k,\bar{y}^k) -\frac{1}{2}\delta\tau_k\|A^*\nabla g_{\mu_k}(A\bar{y}^k)+\nabla_y H(\bar{x}^k,\bar{y}^k)\|^2\notag \\
&\quad -\frac{1}{4}\kappa\sigma_k\|G_{\sigma_k}(\bar{x}^k,\bar{y}^k)\|^2 +(\mu_k-\mu_{k+1})L_g^2.
\end{align}
Summing \eqref{4.10'} from $k=1$ to $k=K$, we have
\begin{align}\label{4.11}
&\sum_{k=1}^K \left(\frac{1}{2}\delta\tau_k\|A^*\nabla g_{\mu_k}(A\bar{y}^k)+\nabla_y H(\bar{x}^k,\bar{y}^k)\|^2 +\frac{1}{4}\kappa\sigma_k\|G_{\sigma_k}(\bar{x}^k,\bar{y}^k)\|^2\right) \notag \\
&\leq \mathcal{L}_{\mu_1}(\bar{x}^1,\bar{y}^1)-\mathcal{L}_{\mu_{K+1}}(\bar{x}^{K+1},\bar{y}^{K+1})+(\mu_1-\mu_{K+1})L_g^2\notag \\
&\leq \mathcal{L}_{\mu_1}(\bar{x}^1,\bar{y}^1)-\mathcal{L}^*+\mu_1L_g^2.
\end{align}
Since $\sigma_k \geq\gamma k^{-\theta}$, $\tau_k\geq\eta k^{-\theta}$, and $M =\min\{\frac{1}{2}\delta\eta, \frac{1}{4}\kappa\gamma\}$, it follows from \eqref{4.11} that
\begin{multline*}
M\left(\sum_{k=1}^{K}k^{-\theta}\right) \min_{1\leq j\leq K}(\|A^*\nabla g_{\mu_j}(A\bar{y}^j)+\nabla_yH(\bar{x}^j,\bar{y}^j)\|^2+
\|G_{\sigma_j}(\bar{x}^j,\bar{y}^j)\|^2) \\ \leq\mathcal{L}_{\mu_1}(\bar{x}^1,\bar{y}^1)
-\mathcal{L}^*+\mu_1L_g^2,
\end{multline*}
Note that
\begin{align*}
\sum_{k=1}^Kk^{-\theta}&\geq \sum_{k=1}^K\int_k^{k+1}x^{-\theta}dx=\int_1^{K+1}x^{-\theta}dx=\frac{1}{1-\theta}((1+K)^{1-\theta}-1)\\
&\geq(\ln 2)K^{1-\theta},
\end{align*}
where the last inequality is obtained by applying Lemma \ref{l:estimate} with $x =K$ and $\alpha =1 -\theta$. We deduce that
\begin{multline*}
\min_{1\leq j\leq K}(\|A^*\nabla g_{\mu_j}(A\bar{y}^j)+\nabla_yH(\bar{x}^j,\bar{y}^j)\|^2+\|G_{\sigma_j}(\bar{x}^j,\bar{y}^j)\|^2) \\ \leq (\ln 2)^{-1}M^{-1}(\mathcal{L}_{\mu_1}(\bar{x}^1,\bar{y}^1)-\mathcal{L}^*+\mu_1L_g^2)k^{\theta-1}.
\end{multline*}
Using the inequality $(\|a\|+\|b\|)^2\leq2(\|a\|^2+\|b\|^2)$, we have
\begin{multline*}
\min_{1\leq j\leq k}(\|A^*\nabla g_{\mu_j}(A\bar{y}^j)+\nabla_yH(\bar{x}^j,\bar{y}^j)\|+\|G_{\sigma_j}(\bar{x}^j,\bar{y}^j)\|) \\ \leq \sqrt{2(\ln 2)^{-1}M^{-1}(\mathcal{L}_{\mu_1}(\bar{x}^1,\bar{y}^1)-\mathcal{L}^*+\mu_1L_g^2)} k^{\frac{\theta-1}{2}}.
\end{multline*}
The proof is complete.
\end{proof}

\begin{proof}
Using Lemmas~\ref{l:e-stationary} and \ref{l:weakcvx}, we obtain
