Let $F:\mathbb{R}^n\rightarrow \mathbb{R}\cup \{+\infty\}$ be a proper lower semicontinuous convex function and $\lambda>0$. The \emph{proximal operator} of $F$ at $v\in \mathbb{R}^n$ is defined by
\begin{align*}
\prox_{\lambda F}(v):=\argmin_{x\in \mathbb{R}^n} \left(F(x)+\frac{1}{2\lambda}\|x-v\|^2\right).
\end{align*}
It is known that $\prox_{\lambda F}$ is nonexpansive, i.e., for all $x,y\in \mathbb{R}^n$,
\begin{align*}
\|\prox_{\lambda F}(x)-\prox_{\lambda F}(y)\|\leq\|x-y\|.
\end{align*}

The \emph{regular subdifferential} of $F$ at $x\in\dom F$ is defined by
$$\widehat{\partial}F(x):=\left\{u\in\mathbb{R}^{n}:\liminf_{y\rightarrow x\atop y\neq x} \frac{\ F(y)- F(x) + \langle u, y-x \rangle}{\|y-x\|}\geq0\right\}.$$
The \emph{limiting subdifferential} of $F$ at $x\in\dom F$ is defined by
 \begin{align*}
\partial F(x) :=\{u \in\mathbb{R}^{n}: \exists\ x_{k}\rightarrow x, \widehat{\partial}F(x_{k}) \ni u_{k} \rightarrow u \ \mathrm{with} \  F(x_{k}) \rightarrow F(x)\}.
\end{align*}
When $F$ is a convex function, both subdifferentials coincide with the subdifferential in the sense of convex analysis, i.e.,
\begin{align*}
\widehat{\partial}F(x)=\partial F(x)=\{u\in\mathbb{R}^{n}: \forall y\in\mathbb{R}^{n},\quad F(y)-F(x)\geq\langle{u,y-x}\rangle\}.
\end{align*}
Clearly, $\widehat{\partial}F(x) \subseteq \partial F(x)$ for all $x\in \mathbb{R}^{n}$ and both of them are closed.  If $G:\mathbb{R}^n\rightarrow \mathbb{R}$ is  a continuously differentiable function, then $\partial G(x)=\{\nabla G(x)\}$ and $\partial(F+G)(x)=\partial F(x)+\nabla G(x)$ for all $x\in \mathbb{R}^n$, where $\nabla G(x)$ denotes the gradient of $G$ at $x$.

\begin{definition}[{\cite[Definition 2.1]{BW}}] Let $F: \mathbb{R}^n\rightarrow (-\infty,+\infty]$ be a proper $\rho$-weakly convex lower semicontinuous function. The Moreau envelope function of $F$ is defined as
\begin{align*}
F_{\mu}(x):=\min_{y\in \mathbb{R}^n}\{F(y)+\frac{1}{2\mu}\|y-x\|^2\},
\end{align*}
where $\mu \in(0,1/\rho)$.
\end{definition}

\begin{align*}
G_\lambda(x,y) =\frac{1}{\lambda}(x -\prox_{\lambda f}(x -\lambda\nabla_x  H(x,y))).
\end{align*}

\begin{definition}
Let $(x^*,y^*)\in \mathbb{R}^n\times \mathbb{R}^m$. We say that $(x^*,y^*)$ is an \emph{$\varepsilon$-approximate stationary point} of problem~\eqref{eq:L1E1} if
\begin{align}\label{wending}
\dist(0,G_\lambda(x^*,y^*))+\dist(-\nabla_yH(x^*,y^*),A^*\partial g(Ay^*))\leq\varepsilon.
\end{align}
Similarly, $(x^*,y^*)$ is said to be an \emph{$\varepsilon$-approximate stationary point} of problem~\eqref{guanghua} if
\begin{align}\label{wending1}
\dist(0,G_\lambda(x^*,y^*))+\dist(-\nabla_yH(x^*,y^*),A^*\nabla g_\mu(Ay^*))\leq\varepsilon.
\end{align}
\end{definition}

\begin{assumption}
\label{a:H}
For any $y\in \mathbb{R}^m$, the partial gradient $\nabla_x H(\cdot,y)$ is $L_{11}$-Lipschitz continuous, i.e.,
\begin{align*}
\forall x_1,x_2\in \mathbb{R}^n,\quad \|\nabla_x H(x_1,y)-\nabla_x H(x_2,y)\|\leq L_{11}\|x_1-x_2\|.
\end{align*}
For any $x\in \mathbb{R}^n$, the partial gradient $\nabla_x H(x,\cdot)$ is $L_{12}$-Lipschitz continuous and the partial gradient $\nabla_y H(x,\cdot)$ is $L_{22}$-Lipschitz continuous, i.e.,
\begin{align*}
&\forall y_1,y_2\in \mathbb{R}^n,\quad \|\nabla_x H(x,y_1)-\nabla_x H(x,y_2)\|\leq L_{12}\|y_1-y_2\|,\\
&\forall y_1,y_2\in\mathbb{ R}^m,\quad \|\nabla_y H(x,y_1)-\nabla_y H(x,y_2)\|\leq L_{22}\|y_1-y_2\|.
\end{align*}
\end{assumption}

\begin{assumption}
\label{a:g}
The function $g$ is $\rho$-weakly convex and $L_g$-Lipschitz continuous. The function $\mathcal{L}$ is bounded below.
\end{assumption}

\begin{algorithm}[htb]
\caption{Variable smoothing alternating proximal gradient (VsaPG)}
\label{algo}

\textbf{Step 1.} Let $x^1 =\bar{x}^1\in \mathbb{R}^{n}$, $y^1 =\bar{y}^1\in \mathbb{R}^{m}$, $\mu_1\in (0, 1/\rho)$, and set $k =1$. Let $\gamma\in (0, +\infty)$, $\eta\in (0, +\infty)$, $\theta\in (0, 1)$, $\beta\in(0, 1]$, $\sigma\in (0, 2/L_{11})$, and let $\alpha\in (0, 1)$ be such that
\begin{align*}
1 -\alpha^2 -\frac{L_{12}^2(1 +\alpha)^2}{L_{11}(L_{22} +2\rho\|A\|^2)} >0.
\end{align*}

\textbf{Step 2.} Let $\mu_{k+1}\in [\mu_k/2, \mu_k]$, $\alpha_k\in [-\alpha, \alpha]$, $\beta_k\in [\beta,1]$, $\sigma_k\in [\gamma k^{-\theta}, \sigma]$, and $\tau_k\in [\eta k^{-\theta}, 1/L_k]$. Compute
\begin{align}
\label{s21}&y^{k+1}=\bar{y}^k-\tau_k(A^*\nabla g_{\mu_k}(A\bar{y}^{k})+\nabla_y H(\bar{x}^k,\bar{y}^k)),\\
\label{s41}&\bar{y}^{k+1}=y^{k+1}+\alpha_k(y^{k+1}-\bar{y}^k),\\
\label{s31}&x^{k+1}=\prox_{\sigma_k f}(\bar{x}^k-\sigma_k\nabla_x H(\bar{x}^k,\bar{y}^{k+1})),\\
\label{s42}&\bar{x}^{k+1} =(1 -\beta_k)\bar{x}^k +\beta_kx^{k+1}.
\end{align}

\textbf{Step 3.} If a termination criterion is not met, set $k =k+1$ and go to Step 2.
\end{algorithm}

Obviously, Assumption \ref{a:g} implies that $\liminf_{k\rightarrow \infty} \mathcal{L}_{\mu_k}(x^k,y^k)>-\infty$. From now on, we denote
\begin{align*}
\mathcal{L}^* :=\liminf_{k\rightarrow \infty} \mathcal{L}_{\mu_k}(x^k,y^k).
\end{align*}

\begin{lemma}[{\cite[Theorem 2.64]{BC}}]
\label{l:descent}
Let $F:\mathbb{R}^n\rightarrow \mathbb{R}$ be a continuously differentiable function whose gradient $\nabla F$ is $L$-Lipschitz continuous with $L>0$. Then, for all $x,y\in \mathbb{R}^n$,
\begin{align*}
|F(y)-F(x)-\langle\nabla F(x),y-x\rangle|\leq\frac{L}{2}\|y-x\|^2.
\end{align*}
\end{lemma}

\begin{lemma}
\label{l:weakcvx}
Let $F: \mathbb{R}^n\rightarrow (-\infty,+\infty]$ be a proper $\rho$-weakly convex and lower semicontinuous function, and let $\mu \in(0,1/\rho)$. Then
\begin{enumerate}
\item
\cite[Corollary 3.4]{HLO} The Moreau envelope function $F_{\mu}$ is continuously differentiable on $\mathbb{R}^n$ and, for all $x\in \mathbb{R}^n$,
\begin{align*}
\nabla F_{\mu}(x) =\frac{1}{\mu}(x-\prox_{\mu F}(x)).
\end{align*}
This gradient is $\max\{\frac{1}{\mu},\frac{\rho}{1-\rho \mu}\}$-Lipschitz continuous.
\item\label{l:weakcvx_inclu}
\cite[Lemma 3.2]{BW} $\nabla{F_{\mu}(x)}\in \partial F(\prox_{\mu F}(x))$.
\end{enumerate}
\end{lemma}

\begin{lemma}[{\cite[Lemma 3.3]{BW}}]\label{2.6} Let $F: \mathbb{R}^n\rightarrow (-\infty,\infty)$ be a $\rho$-weakly convex function and $L_F$-Lipschitz continuous, and let $\mu \in (0,1/\rho)$. Then the Moreau envelope $F_\mu$ is Lipschitz continuous and, for all $x\in \mathbb{R}^n$,
\begin{align*}
\|\nabla F_\mu(x)\|\leq L_F \text{~~and~~} \|x-\prox_{\mu F}(x)\|\leq \mu L_F.
\end{align*}
\end{lemma}

\begin{lemma}[{\cite[Lemma~\ref{l:LL}]{BW}}]
\label{l:MoreauEnv}
Let $F: \mathbb{R}^n\rightarrow (-\infty,+\infty]$ be a proper $\rho$-weakly convex lower semicontinuous function, let $\mu_1$ and $\mu_2$ be parameters such that $0< \mu_2 \leq \mu_1 < 1/\rho$. Then
\begin{align*}
F_{\mu_2}(x)\leq F_{\mu_1}(x)+\frac{\mu_1(\mu_1-\mu_2)}{2\mu_2}\|
\nabla F_{\mu_1}(x)\|^2.
\end{align*}
If $F$ is additionally $L_F$-Lipschitz continuous, then
\begin{align*}
F_{\mu_2}\leq F_{\mu_1}+\frac{\mu_1(\mu_1-\mu_2)}{2\mu_2}(L_F)^2.
\end{align*}
\end{lemma}

\begin{lemma}\label{l:estimate}
Let $x\in [1, +\infty)$ and $\alpha\in [0, 1]$. Then
