\mathcal{L}_{\mu_{k}}(\bar{x}^{k+1},\bar{y}^{k+1}) &\leq \mathcal{L}_{\mu_{k}}(\bar{x}^k,\bar{y}^k)
-\frac{1}{2}\delta\tau_k\|A^*\nabla g_{\mu_k}(A\bar{y}^k)+\nabla_y H(\bar{x}^k,\bar{y}^k)\|^2\notag \\
&\quad -\frac{1}{4}\kappa\sigma_k\|G_{\sigma_k}(\bar{x}^k,\bar{y}^k)\|^2 +(\mu_k-\mu_{k+1})L_g^2,
\end{align*}
where $\delta :=1 -\alpha^2 -\frac{L_{12}^2(1+\alpha)^2}{L_{11}(L_{22} +2\rho\|A\|^2)} >0$ and $\kappa :=\min\{(2 -L_{11}\beta\sigma)\beta, 2 -L_{11}\sigma\} >0$.
\end{lemma}

\begin{proof}
From the Lipschitz continuity of $\nabla_x \Phi_k(\cdot,\bar{y}^{k+1})$ and $\nabla_y\Phi_k(\bar{x}^k, \cdot)$, Lemma \ref{l:descent} implies that
\begin{align*}
\Phi_k(\bar{x}^{k+1},\bar{y}^{k+1}) &\leq\Phi_k(\bar{x}^{k},\bar{y}^{k+1}) +\langle\nabla_x\Phi_k(\bar{x}^k,\bar{y}^{k+1}),\bar{x}^{k+1}-\bar{x}^k\rangle+\frac{L_{11}}{2}\|\bar{x}^{k+1}-\bar{x}^k\|^2, \\
\Phi_k(\bar{x}^k,\bar{y}^{k+1}) &\leq \Phi_k(\bar{x}^k,\bar{y}^k) +\langle\nabla_y\Phi_k(\bar{x}^k,\bar{y}^k),\bar{y}^{k+1}-\bar{y}^k\rangle+\frac{L_k}{2}\|\bar{y}^{k+1}-\bar{y}^k\|^2.
\end{align*}
We note that
\begin{align}\label{eq:grad_y Phi_k}
\nabla_y\Phi_k(\bar{x}^k,\bar{y}^k) =A^*\nabla g_{\mu_k}(A\bar{y}^k)+\nabla_y H(\bar{x}^k,\bar{y}^k)
\end{align}
and from \eqref{s21}, \eqref{s41}, \eqref{s42}, and \eqref{zhu4.2} that
\begin{align*}
\bar{x}^{k+1}-\bar{x}^k &=\beta_k(x^{k+1}-\bar{x}^k)=-\beta_k\sigma_k G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1}), \\
\bar{y}^{k+1}-\bar{y}^k &=(1+\alpha_k)(y^{k+1}-\bar{y}^k) =-(1+\alpha_k)\tau_k \nabla_y\Phi_k(\bar{x}^k,\bar{y}^k).
\end{align*}
Therefore,
\begin{align}\label{8.7}
&\Phi_k(\bar{x}^{k+1},\bar{y}^{k+1}) \notag \\
&\leq \Phi_k(\bar{x}^k,\bar{y}^k) +\langle\nabla_x\Phi_k(\bar{x}^k,\bar{y}^{k+1}),\bar{x}^{k+1}-\bar{x}^k\rangle+\frac{L_{11}}{2}\|\bar{x}^{k+1}-\bar{x}^k\|^2 \notag \\
&\quad +\langle\nabla_y\Phi_k(\bar{x}^k,\bar{y}^k),\bar{y}^{k+1}-\bar{y}^k\rangle+\frac{L_k}{2}\|\bar{y}^{k+1}-\bar{y}^k\|^2 \notag \\
&= \Phi_k(\bar{x}^k,\bar{y}^k) -\beta_k\sigma_k\langle\nabla_x\Phi_k(\bar{x}^k,\bar{y}^{k+1}),G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\rangle \notag \\
&\quad +\frac{1}{2}L_{11}\beta_k^2\sigma_k^2\|G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\|^2 \notag\\
&\quad -\frac{1}{2}(2 +2\alpha_k -L_k(1+\alpha_k)^2\tau_k)\tau_k\|\nabla_y\Phi_k(\bar{x}^k,\bar{y}^k)\|^2.
\end{align}
By Lemma \ref{l:MoreauEnv} and the fact that $\mu_{k+1}\in [\mu_k/2, \mu_k]$,
\begin{align}\label{8.8}
g_{\mu_{k+1}}(Ay)\leq g_{\mu_k}(Ay) +\frac{\mu_k(\mu_k-\mu_{k+1})}{2\mu_{k+1}}L_g^2\leq g_{\mu_k}(Ay) +(\mu_k-\mu_{k+1})L_g^2.
\end{align}
Adding $H(x,y)$ to both sides of \eqref{8.8} yields
\begin{align}\label{3.4}
\Phi_{k+1}(x,y)\leq \Phi_k(x,y) +(\mu_k-\mu_{k+1})L_g^2.
\end{align}
Letting $x =\bar{x}^{k+1}$, $y =\bar{y}^{k+1}$ in \eqref{3.4} and combining it with \eqref{8.7}, we obtain that
\begin{align}\label{4.4}
&\Phi_{k+1}(\bar{x}^{k+1},\bar{y}^{k+1}) \notag \\
&\leq \Phi_k(\bar{x}^k,\bar{y}^k) -\beta_k\sigma_k\langle\nabla_x\Phi_k(\bar{x}^k,\bar{y}^{k+1}),G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\rangle \notag \\
&\quad +\frac{1}{2}L_{11}\beta_k^2\sigma_k^2\|G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\|^2 \notag\\
&\quad -\frac{1}{2}(2 +2\alpha_k -L_k(1+\alpha_k)^2\tau_k)\tau_k\|\nabla_y\Phi_k(\bar{x}^k,\bar{y}^k)\|^2 +(\mu_k-\mu_{k+1})L_g^2.
\end{align}
By the first-order optimality condition of \eqref{s31},
\begin{align*}
0\in \partial f(x^{k+1})+\frac{1}{\sigma_k}(x^{k+1}-\bar{x}^k+\sigma_k\nabla_x H(\bar{x}^k,\bar{y}^{k+1})),
\end{align*}
or equivalently,
\begin{align*}
\frac{1}{\sigma_k}(\bar{x}^k -x^{k+1}) -\nabla_x H(\bar{x}^k,\bar{y}^{k+1})\in \partial f(x^{k+1}).
\end{align*}
Combining with the convexity of $f$ and \eqref{zhu4.2}, it follows that
\begin{align}\label{8.9}
f(x^{k+1}) &\leq f(\bar{x}^k) -\left\langle \frac{1}{\sigma_k}(\bar{x}^k -x^{k+1}) -\nabla_x H(\bar{x}^k,\bar{y}^{k+1}), \bar{x}^k -x^{k+1}\right\rangle \notag \\
&= f(\bar{x}^k) -\frac{1}{\sigma_k}\|\bar{x}^k -x^{k+1}\|^2 +\langle \nabla_x H(\bar{x}^k,\bar{y}^{k+1}), \bar{x}^k -x^{k+1}\rangle\notag \\
&= f(\bar{x}^k) -\sigma_k\|G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\|^2 +\sigma_k\langle\nabla_x H(\bar{x}^k,\bar{y}^{k+1}),G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\rangle.
\end{align}
Again by the convexity of $f$ and \eqref{s42},
\begin{align*}
f(\bar{x}^{k+1})&=f\big(\beta_k x^{k+1}+(1-\beta_k)\bar{x}^k\big)
\leq \beta_k f(x^{k+1})+(1-\beta_k)f(\bar{x}^k).
\end{align*}
This together with \eqref{8.9} gives
\begin{align}\label{4.5}
f(\bar{x}^{k+1})&\leq f(\bar{x}^k) -\beta_k\sigma_k\|G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\|^2 \notag \\
&\quad +\beta_k\sigma_k\langle\nabla_xH(\bar{x}^k,\bar{y}^{k+1}),G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\rangle.
\end{align}
We now combine \eqref{4.4} and \eqref{4.5} to obtain
\begin{align}\label{4.10}
&\mathcal{L}_{\mu_{k}}(\bar{x}^{k+1},\bar{y}^{k+1}) \notag \\
&\leq \mathcal{L}_{\mu_{k}}(\bar{x}^k,\bar{y}^k) -\frac{1}{2}(2 +2\alpha_k -L_k(1+\alpha_k)^2\tau_k)\tau_k\|\nabla_y\Phi_k(\bar{x}^k,\bar{y}^k)\|^2 \notag \\ &\quad -\frac{1}{2}(2 -L_{11}\beta_k\sigma_k)\beta_k\sigma_k\|G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\|^2 +(\mu_k-\mu_{k+1})L_g^2.
\end{align}
Next, using Remark~\ref{r:G(x,.)},
\begin{align*}
\|G_{\sigma_k}(\bar{x}^k,\bar{y}^k)\|&=\|G_{\sigma_k}(\bar{x}^k,\bar{y}^k)-G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})+G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\|\notag \\
&\leq\|G_{\sigma_k}(\bar{x}^k,\bar{y}^k)-G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\|+\|G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\|\notag \\
&\leq L_{12}\|\bar{y}^{k+1}-\bar{y}^k\|+\|G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\|.
\end{align*}
Squaring and applying the inequality $\frac{1}{2}(a+b)^2 \leq a^2 +b^2$, we get
\begin{align*}
\frac{1}{2}\|G_{\sigma_k}(\bar{x}^k,\bar{y}^k)\|^2 &\leq L_{12}^2\|\bar{y}^{k+1}-\bar{y}^k\|^2 +\|G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\|^2 \\
&= L_{12}^2(1+\alpha_k)^2\tau_k^2\|\nabla_y\Phi_k(\bar{x}^k,\bar{y}^k)\|^2 +\|G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\|^2.
\end{align*}
which, combined with \eqref{eq:grad_y Phi_k} and \eqref{4.10}, implies that
\begin{align*}
\mathcal{L}_{\mu_{k}}(\bar{x}^{k+1},\bar{y}^{k+1}) &\leq \mathcal{L}_{\mu_{k}}(\bar{x}^k,\bar{y}^k) -\frac{1}{2}\delta_k\tau_k\|A^*\nabla g_{\mu_k}(A\bar{y}^k)+\nabla_y H(\bar{x}^k,\bar{y}^k)\|^2 \notag \\
&\quad -\frac{1}{4}\kappa_k\sigma_k\|G_{\sigma_k}(\bar{x}^k,\bar{y}^{k+1})\|^2 +(\mu_k-\mu_{k+1})L_g^2,
\end{align*}
where
\begin{align*}
\delta_k &:=2 +2\alpha_k -L_k(1+\alpha_k)^2\tau_k -(2 -L_{11}\beta_k\sigma_k)\sigma_k\beta_kL_{12}^2(1+\alpha_k)^2\tau_k, \\
\kappa_k &:=(2 -L_{11}\beta_k\sigma_k)\beta_k.
\end{align*}
Noting that $\tau_k\leq 1/L_k$ and that
\begin{align*}
(2 -L_{11}\beta_k\sigma_k)\sigma_k\beta_k\leq \frac{1}{L_{11}}\left(\frac{2 -L_{11}\beta_k\sigma_k +L_{11}\beta_k\sigma_k}{2}\right)^2 =\frac{1}{L_{11}},
\end{align*}
we have
\begin{align*}
\delta_k &\geq 2 +2\alpha_k -(1+\alpha_k)^2 -\frac{L_{12}^2}{L_{11}L_k}(1+\alpha_k)^2 \\
&= 1 -\alpha_k^2 -\frac{L_{12}^2}{L_{11}L_k}(1+\alpha_k)^2 \\
&\geq \delta =1 -\alpha^2 -\frac{L_{12}^2(1+\alpha)^2}{L_{11}(L_{22} +2\rho\|A\|^2)},
\end{align*}
where the last inequality follows from from the fact that $\alpha_k\in [-\alpha, \alpha]\subseteq [-1, \alpha]$ and that $L_k =L_{22} +\|A\|^2\max\{\frac{1}{\mu_k}, \frac{\rho}{1 -\rho\mu_k}\}\geq L_{22} +2\rho\|A\|^2$ since
\begin{align*}
\max\left\{\frac{1}{\mu_k}, \frac{\rho}{1 -\rho\mu_k}\right\} =\begin{cases}
\frac{1}{\mu_k} &\text{if~} 0 < \mu_k \leq \frac{1}{2\rho}, \\
\frac{\rho}{1 -\rho\mu_k} &\text{if~} \frac{1}{2\rho} < \mu_k < \frac{1}{\rho}.
\end{cases}
\end{align*}
Finally, we derive from $\sigma_k\in \sigma$ and $\beta_k\in [\beta, 1]$ that
\begin{align*}
\kappa_k =(2 -L_{11}\beta_k\sigma_k)\beta_k \geq (2 -L_{11}\beta_k\sigma)\beta_k \geq \kappa =\min\{(2 -L_{11}\beta\sigma)\beta, 2 -L_{11}\sigma\}
\end{align*}
as $(2 -L_{11}\beta_k\sigma)\beta_k$ is a quadratic function of $\beta_k$ with leading coefficient $-L_{11}\sigma <0$. This completes the proof.
\end{proof}

From the Lipschitz continuity of $\nabla_x \Phi_k(\cdot,\bar{y}^{k+1})$ and $\nabla_y\Phi_k(\bar{x}^k, \cdot)$, Lemma \ref{l:descent} implies that
