\begin{lemma}
\label{l:e-stationary}
Suppose that Assumptions~\ref{a:H} and \ref{a:g} hold. Let $(\bar{x}^k,\bar{y}^k)$ be the sequence generated by Algorithm~\ref{algo}. Then
\begin{align*}
\min_{1\leq j\leq k}\left(\|A^*\nabla g_{\mu_j}(A\bar{y}^j)+\nabla_y H(\bar{x}^j,\bar{y}^j)\|+\|G_{\sigma_j}(\bar{x}^j,\bar{y}^j)\|\right)
\leq \Theta k^{\frac{\theta-1}{2}},
\end{align*}
where $\Theta :=\sqrt{2(\ln 2)^{-1}M^{-1}(\mathcal{L}_{\mu_1}(\bar{x}^1,\bar{y}^1)-\mathcal{L}^*+\mu_1L_g^2)}$ and
\begin{align*}
M :=\min\left\{\frac{(1 -\alpha^2)\eta}{2} -\frac{L_{12}^2(1+\alpha)^2\eta}{2L_{11}(L_{22} +2\rho\|A\|^2)}, \frac{(2 -L_{11}\beta\sigma)\beta\gamma}{4}, \frac{(2 -L_{11}\sigma)\gamma}{4}\right\}.
\end{align*}
\end{lemma}

\begin{proof}
According to Lemma~\ref{l:LL},
\begin{align}\label{4.10'}
\mathcal{L}_{\mu_{k}}(\bar{x}^{k+1},\bar{y}^{k+1}) &\leq \mathcal{L}_{\mu_{k}}(\bar{x}^k,\bar{y}^k) -\frac{1}{2}\delta\tau_k\|A^*\nabla g_{\mu_k}(A\bar{y}^k)+\nabla_y H(\bar{x}^k,\bar{y}^k)\|^2\notag \\
&\quad -\frac{1}{4}\kappa\sigma_k\|G_{\sigma_k}(\bar{x}^k,\bar{y}^k)\|^2 +(\mu_k-\mu_{k+1})L_g^2.
\end{align}
