\begin{multline*}
M\left(\sum_{k=1}^{K}k^{-\theta}\right) \min_{1\leq j\leq K}(\|A^*\nabla g_{\mu_j}(A\bar{y}^j)+\nabla_yH(\bar{x}^j,\bar{y}^j)\|^2+
\|G_{\sigma_j}(\bar{x}^j,\bar{y}^j)\|^2) \\ \leq\mathcal{L}_{\mu_1}(\bar{x}^1,\bar{y}^1)
-\mathcal{L}^*+\mu_1L_g^2,
\end{multline*}

Note that
\begin{align*}
\sum_{k=1}^Kk^{-\theta}&\geq \sum_{k=1}^K\int_k^{k+1}x^{-\theta}dx=\int_1^{K+1}x^{-\theta}dx=\frac{1}{1-\theta}((1+K)^{1-\theta}-1)\\
&\geq(\ln 2)K^{1-\theta},
\end{align*}
where the last inequality is obtained by applying Lemma \ref{l:estimate} with $x =K$ and $\alpha =1 -\theta$. We deduce that

\begin{multline*}
\min_{1\leq j\leq K}(\|A^*\nabla g_{\mu_j}(A\bar{y}^j)+\nabla_yH(\bar{x}^j,\bar{y}^j)\|^2+\|G_{\sigma_j}(\bar{x}^j,\bar{y}^j)\|^2) \\ \leq (\ln 2)^{-1}M^{-1}(\mathcal{L}_{\mu_1}(\bar{x}^1,\bar{y}^1)-\mathcal{L}^*+\mu_1L_g^2)k^{\theta-1}.
\end{multline*}

Using the inequality $(\|a\|+\|b\|)^2\leq2(\|a\|^2+\|b\|^2)$, we have
\begin{multline*}
\min_{1\leq j\leq k}(\|A^*\nabla g_{\mu_j}(A\bar{y}^j)+\nabla_yH(\bar{x}^j,\bar{y}^j)\|+\|G_{\sigma_j}(\bar{x}^j,\bar{y}^j)\|) \\ \leq \sqrt{2(\ln 2)^{-1}M^{-1}(\mathcal{L}_{\mu_1}(\bar{x}^1,\bar{y}^1)-\mathcal{L}^*+\mu_1L_g^2)} k^{\frac{\theta-1}{2}}.
\end{multline*}
The proof is complete.
